export const woodlandViews={
 'eco-rainforest-deforestation':[['conversion','Forest → farmland'],['access','Roads & access'],['demand','Compare demand'],['choices','Drivers interact']],
 'eco-rainforest-management':[['governance','Rights & monitoring'],['locator','Locate Petén'],['value','Forest-product value'],['tourism','Visitor pathway']],
 'eco-woodland-system':[['seasons','A year in woodland'],['structure','Living & non-living'],['water','Water pathways'],['people','People & habitat']],
 'eco-woodland-cycles':[['cycle','Stores & transfers'],['autumn','Autumn litterfall'],['spring','Spring release & uptake'],['web','Food-web energy']],
 'eco-woodland-adaptations':[['leaves','Winter water balance'],['light','Spring light window'],['migration','Seasonal migration'],['winter','Winter strategies']]
};
export const woodlandRequirements=Object.fromEntries(Object.entries(woodlandViews).map(([k,v])=>[k,v.map(x=>x[0])]));
export const woodlandAnimated=(k,v)=>({
 'eco-rainforest-deforestation':['conversion','access'],
 'eco-rainforest-management':['governance','value','tourism'],
 'eco-woodland-system':['seasons','water'],
 'eco-woodland-cycles':['cycle','autumn','spring'],
 'eco-woodland-adaptations':['leaves','light','migration']
}[k]||[]).includes(v);
const text=(x,y,s,z=13)=>`<text x="${x}" y="${y}" font-size="${z}">${s}</text>`;
const line=(d,c='#b9cdd6',w=3)=>`<path d="${d}" fill="none" stroke="${c}" stroke-width="${w}" stroke-linecap="round"/>`;
const arrow=d=>`<path d="${d}" fill="none" stroke="#edb59f" stroke-width="3" marker-end="url(#w3Arrow)"/>`;
const dot=(x,y,r=5,c='#edb59f')=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${c}"/>`;
const box=(x,y,w,a,b='')=>`<rect x="${x}" y="${y}" width="${w}" height="${b?66:44}" rx="12" fill="#365469" stroke="#a8c2cc"/>`+text(x+12,y+26,a,12)+(b?text(x+12,y+48,b,11):'');
const tree=(x,y,h=140,leaves=1,colour='#a9bfa2')=>line(`M${x} ${y}V${y-h+25}M${x} ${y-55}l-25 -30M${x} ${y-80}l28 -27`,'#c6ac8a',7)+`<g opacity="${leaves}"><ellipse cx="${x}" cy="${y-h+40}" rx="38" ry="40" fill="${colour}"/><ellipse cx="${x-22}" cy="${y-h+65}" rx="30" ry="30" fill="${colour}"/><ellipse cx="${x+22}" cy="${y-h+65}" rx="30" ry="30" fill="${colour}"/></g>`;
const ground=()=>`<path d="M20 280Q220 270 420 285V310H20Z" fill="#847465"/>`;
const svg=(b,c)=>`<svg class="geo-scene" viewBox="0 0 440 350" role="img" aria-label="${c.replaceAll('&','&amp;').replaceAll('"','&quot;')}"><defs><marker id="w3Arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0L10 5 0 10Z" fill="#edb59f"/></marker></defs><g fill="#eef2f2" font-family="sans-serif">${b}</g></svg><p class="geo-caption">${c}</p>`;
export function woodlandBudget(stage,t=1){t=Math.max(0,Math.min(1,Number(t)||0));return stage==='autumn'?{biomass:40-8*t,litter:20+8*t,soil:40}:stage==='spring'?{biomass:32+6*t,litter:28-4*t,soil:40-2*t}:{biomass:40,litter:20,soil:40};}
export const landDemand=(population,hectaresPerPerson)=>population*hectaresPerPerson;
const stores=(s,labels=true)=>`<circle cx="220" cy="100" r="49" fill="#829f8f"/><circle cx="100" cy="245" r="36" fill="#a58b72"/><circle cx="330" cy="245" r="47" fill="#7495a6"/>`+text(188,100,'Biomass',13)+text(83,244,'Litter',13)+text(316,244,'Soil',13)+(s?text(206,122,s.biomass.toFixed(1),12)+text(86,264,s.litter.toFixed(1),12)+text(316,266,s.soil.toFixed(1),12):'')+arrow('M186 140L124 209')+arrow('M143 245H276')+arrow('M312 200L251 145')+(labels?text(70,168,'Litterfall',11)+text(154,228,'Decomposition',11)+text(298,167,'Uptake',11):'');
export function woodlandScene(k,v,t=0){if(!woodlandViews[k])return '';v=woodlandRequirements[k].includes(v)?v:woodlandRequirements[k][0];t=woodlandAnimated(k,v)?Math.max(0,Math.min(1,Number(t)||0)):0;let b='',c='';
if(k==='eco-rainforest-deforestation'){
 if(v==='conversion'){b=text(20,28,'A LAND-USE CHANGE,NOT SEASONAL LEAF LOSS',13)+ground();for(let i=0;i<5;i++){const x=55+i*80,removed=t>i/5;b+=removed?`<rect x="${x-23}" y="238" width="46" height="35" rx="5" fill="#c9b38a"/>`+line(`M${x-15} 240v28m15-28v28m15-28v28`,'#847657',2):tree(x,279,145+i%2*35);}b+=text(20,75,'Forest cover converted progressively',13)+text(20,329,'Pasture / crops occupy the cleared area',12);c='Worked land-conversion sequence: trees are replaced by agricultural land. Stumps alone would not prove permanent conversion; the replacement use matters. Timing,tree count and area are symbolic,not an observed site or predicted clearance rate.';}
 else if(v==='access'){b=text(20,28,'EXTRACTION CAN OPEN ACCESS',15)+ground()+tree(65,280,150)+tree(190,280,190)+tree(345,280,160)+`<path d="M220 310L${220-100*t} ${300-160*t}" stroke="#d4c4a4" stroke-width="18"/>`+dot(220-100*t,300-160*t,7)+box(230,70,180,'Road / extraction','Access may expand')+arrow('M320 145L280 215')+text(20,329,'Later conversion depends on rules and decisions',12);c='A moving marker follows a growing access route. Roads can fragment habitat and enable later farming or settlement. Such follow-on clearance is possible,not inevitable; rights,enforcement and economic choices influence outcomes. This is a causal example,not a real road map.';}
 else if(v==='demand'){const a=landDemand(100,.2),d=landDemand(100,.4);b=text(20,28,'EQUAL POPULATION · DIFFERENT LAND DEMAND',13)+text(20,65,'Invented scenarios:100people in each',13)+`<rect x="65" y="${270-a*4}" width="100" height="${a*4}" rx="6" fill="#a8c6c5"/><rect x="250" y="${270-d*4}" width="100" height="${d*4}" rx="6" fill="#efb59f"/>`+text(70,295,'A:0.2ha each',12)+text(255,295,'B:0.4ha each',12)+text(95,175,'20ha',15)+text(280,95,'40ha',15)+text(20,330,'Farmed-land demand ≠ predicted forest loss',12);c='Each bar is combined farmed-land demand for100people:20ha versus40ha. Scale: bar height4display units per hectare. These invented equal-population comparisons isolate per-person demand; they do not measure forest loss or predict resource exhaustion. Yields,trade,waste and rights matter too.';}
 else{b=text(20,28,'DIRECT CAUSES AND UNDERLYING DRIVERS',13)+box(25,70,180,'Markets / livelihoods','Demand and prices')+box(235,70,180,'Population / access','Needs and inequality')+arrow('M115 144L160 195')+arrow('M325 144L280 195')+box(60,205,320,'Conversion / extraction','Filtered by rights and governance')+text(20,325,'Same demand does not imply the same land outcome',12);c='This static causal comparison links agriculture,resource extraction and population pressure to wider economic and social conditions. Communities have varied roles and rights; population alone is not a sufficient explanation and overseas demand can also matter.';}
}
if(k==='eco-rainforest-management'){
 if(v==='locator'){b=text(20,28,'PETÉN · NORTHERN GUATEMALA',15)+`<path d="M80 90H245L280 170 235 260 150 300 80 230Z" fill="#7f9d8e" stroke="#c4d7d3" stroke-width="2"/><path d="M80 90H245L259 127H80Z" fill="#b5c7a5"/>`+dot(190,110,6)+arrow('M198 110L290 100')+text(294,100,'Petén',15)+text(294,125,'MBR',13)+text(25,70,'Mexico (north)',12)+text(285,175,'Belize (east)',12)+text(105,220,'Guatemala',14)+text(20,330,'Schematic locator · not boundaries or GIS',12);c='The Maya Biosphere Reserve (MBR) lies in Petén,northern Guatemala,near Mexico and Belize. Uaxactún is a community forest-management example in this region. The outline and marker are schematic for orientation,not a surveyed boundary,map scale or forest-loss dataset.';}
 else if(v==='governance'){b=text(20,28,'RIGHTS + RULES + COMMUNITY MONITORING',13)+`<rect x="40" y="72" width="360" height="195" rx="18" fill="#284c4c" stroke="#b4c8bb" stroke-dasharray="7 5"/>`+tree(110,250,125)+tree(220,250,160)+tree(330,250,130)+dot(55+330*t,265,8)+text(50,96,'Community concession · multiple-use zone',11)+text(20,305,'OMYC / CONAP agreement · local stewardship',12)+text(20,330,'Monitoring makes a boundary meaningful',12);c='Worked monitoring route illustrates the role of community organisation and enforceable concession rules. OMYC’s1999government concession at Uaxactún provides a named governance example. This is not its actual boundary or patrol route. Rights and participation can support stewardship,but a boundary alone does not prove compliance.';}
 else if(v==='value'){b=text(20,28,'VALUE LINKED TO MAINTAINED FOREST',14)+tree(85,245,155)+box(180,80,235,'Regulated products','Timber / xate / ramón nuts')+box(180,210,235,'Livelihoods + stewardship','Income can support care')+arrow('M115 150L170 112')+arrow('M300 151V200')+arrow('M180 240L130 245')+dot(125+45*t,140-28*t)+dot(300,155+40*t)+text(20,325,'Conversion profits can create opposite incentives',12);c='Product value can support keeping forest standing when harvesting is regulated,ecological limits are respected and communities benefit. CONAP describes xate,ramón nuts and other products at Uaxactún. Increasing the price of a commodity that requires clearance can instead raise conversion pressure. This is an incentive pathway,not measured profits or guaranteed outcomes.';}
 else{b=text(20,28,'VISIT → LOCAL SERVICES → CONSERVATION',13)+tree(80,260,160)+tree(350,260,190)+line('M50 285Q220 140 390 285','#d2bd9f',5)+dot(50+340*t,285-100*Math.sin(Math.PI*t),7)+box(120,65,200,'Guides / visitor services','Forest + Maya heritage')+text(25,315,'Visitor limits · fair benefits · habitat checks',12)+text(25,335,'Demand can vary; revenue is only one measure',11);c='Uaxactún’s community offers forest and Maya-heritage visits. Local services can diversify incomes and give value to maintained forest. Visitor disturbance,waste,benefit sharing and fluctuating demand need management. The moving visitor is a worked pathway,not a measured carrying capacity or evidence that all tourism is sustainable.';}
}
if(k==='eco-woodland-system'){
 if(v==='seasons'){const phase=Math.min(3,Math.floor(t*4)),names=['Spring:leaf-out','Summer:full canopy','Autumn:leaf fall','Winter:bare branches'],cover=[.45,1,.55,0][phase];b=text(20,28,'ONE YEAR · SYMBOLIC SEASONS',15)+ground()+tree(95,280,155,cover,phase===2?'#d0a27e':'#a9bfa2')+tree(220,280,200,cover,phase===2?'#d0a27e':'#a9bfa2')+tree(350,280,165,cover)+dot(65+310*t,55,10,'#efcf8f')+text(20,330,names[phase],15);c='Leaf cover changes through a simplified temperate woodland year. Seasonal temperature,light and water conditions affect growth and organisms. Months are compressed equally for teaching,not measured phenology; species and years vary. Bare deciduous trees can remain alive and dormant.';}
 else if(v==='water'){b=text(20,28,'WATER THROUGH THE WOODLAND',15)+ground()+tree(130,280,180)+tree(300,280,160)+arrow('M45 65V155')+arrow('M240 175V290')+arrow('M365 255V80')+dot(45,65+90*t,4,'#b6dae8')+dot(240,175+115*t,4,'#b6dae8')+dot(365,255-175*t,4,'#b6dae8')+text(22,55,'Rain',12)+text(210,315,'Infiltration ↓',12)+text(280,67,'Transpiration ↑',12)+text(20,335,'Interception · throughfall · soil water · drainage',11);c='Rain can be intercepted,evaporate or reach the soil by throughfall and stemflow. Infiltration supplies soil water; roots take up water and transpiration returns vapour. Seasonal rates vary; winter does not stop every pathway. Dot sizes and equal timings are not measured quantities or a closed water balance.';}
 else if(v==='structure'){b=text(20,28,'BIOTIC LIFE IN ABIOTIC CONDITIONS',14)+ground()+tree(100,280,165)+tree(290,280,200)+text(20,65,'Light / temperature / rainfall',13)+text(25,320,'Soil:minerals,water,air AND organisms',12)+text(200,100,'Trees / birds',12)+text(205,240,'Shrubs / fungi',12);c='Trees,other plants,animals,fungi and microbes are living components. Light,temperature,water and mineral conditions are abiotic. Soil contains organisms as well as non-living components. This is a structural schematic,not a species inventory or claim every woodland has identical soil.';}
 else{b=text(20,28,'PEOPLE CHANGE STRUCTURE AND HABITAT',14)+box(20,70,190,'Small managed gaps','More ground light')+box(230,70,190,'Old trees / dead wood','Varied habitat features')+tree(85,285,130)+tree(345,285,165)+arrow('M185 185L210 240')+text(20,330,'Effects depend on intensity,site and objectives',12);c='Timber use,recreation,conservation and coppicing can change woodland age structure,light and habitat. This comparison shows possible managed features,not a universal prescription or proof every managed or unmanaged woodland has the same biodiversity.';}
}
if(k==='eco-woodland-cycles'){
 if(v==='web'){b=text(20,28,'FOOD → CONSUMER · ENERGY TRANSFER',14)+box(20,70,175,'Oak leaves')+box(245,70,175,'Caterpillars')+box(245,190,175,'Insect-eating birds')+box(20,250,195,'Decomposers')+arrow('M205 92H235')+arrow('M330 125V180')+arrow('M100 125V240')+arrow('M270 245L225 268')+text(20,330,'Sunlight input · heat loss · nutrients recycled separately',11);c='Selected woodland feeding links transfer energy from food to consumer. Dead material supplies decomposers. Energy is dissipated as heat and needs continuing input,whereas nutrients can be recycled through soil and organisms. This is not a complete web,measured transfer efficiency or a closed energy cycle.';}
 else if(v==='cycle'){const n=Math.min(2,Math.floor(t*3)),u=t*3-n,p=[[186,140,124,209],[143,245,276,245],[312,200,251,145]][n];b=text(20,28,'GERSMEHL · STORES AND FLOWS',15)+stores(null)+dot(p[0]+(p[2]-p[0])*u,p[1]+(p[3]-p[1])*u)+text(20,330,'Circle sizes schematic · external flows not shown',12);c='Litterfall moves nutrients from biomass to litter; decomposition releases nutrients into soil; uptake moves them into biomass. Warmth,moisture and organisms affect rates. Rainfall/weathering inputs and leaching/removal outputs also matter in real woodland. Sizes and timings here are not universal percentages or measured transfer rates.';}
 else{const s=woodlandBudget(v,t);b=text(20,28,v==='autumn'?'AUTUMN ·8UNITS MOVE TO LITTER':'SPRING ·4DECAY /6UPTAKE',14)+stores(s)+text(20,315,`Closed example total:${(s.biomass+s.litter+s.soil).toFixed(0)} nutrient units`,13)+text(20,336,'Invented units · no external inputs or losses',11);if(v==='autumn')b+=dot(186-62*t,140+69*t);else b+=dot(143+133*t,245)+dot(312-61*t,200-55*t);c=v==='autumn'?'Invented closed nutrient budget starts40biomass,20litter,40soil. Eight units transfer by litterfall to finish32,28,40; total100. Cold conditions can slow decomposition so litter accumulates. This isolated transfer is not the complete annual cycle or measured woodland data.':'After the autumn example,stores start32,28,40. Four units pass from litter to soil and six from soil into growing biomass; final38,24,38,total100. Real transfers overlap and include inputs/outputs. Symbolic timing does not imply all decomposition or uptake happens only in spring.';}
}
if(k==='eco-woodland-adaptations'){
 if(v==='leaves'){const cover=1-t;b=text(20,28,'LEAF LOSS REDUCES WINTER WATER DEMAND',13)+ground()+tree(140,280,195,cover)+line('M110 300l-35 20m65-20v25m30-25 35 20','#c6ac8a',4)+arrow('M330 260V100')+dot(330,260-160*t,3+4*cover,'#b6dae8')+text(250,80,'Less leaf area',13)+text(245,300,'Cold soil may',12)+text(245,320,'restrict uptake',12);c='As leaves are shed,the surface available for transpiration falls. This helps when winter light is limited and cold or frozen soil restricts water uptake. Broad,relatively thin leaves are useful for light capture in the growing season. Leaf loss does not mean tree death; this is a qualitative balance,not a measured water flux.';}
 else if(v==='light'){b=text(20,28,'SPRING LIGHT WINDOW BEFORE CANOPY CLOSURE',12)+ground()+tree(110,280,195,t)+tree(320,280,220,t);for(let i=0;i<5;i++)b+=`<path d="M${50+i*80} 55V270" stroke="#f0d49a" stroke-width="3" opacity="${1-.8*t}"/>`;b+=text(20,315,t<.5?'Early spring:more ground light':'Later:leaf cover shades ground',13)+text(20,336,'Ground plants can flower before full leaf-out',12);c='Increasing canopy leaf cover reduces light reaching many ground plants. Early spring growth and flowering can use the light window before canopy closure. Seasonal energy limits help explain the broad moderate-biodiversity comparison with tropical rainforest,not a fixed species count or lack of valuable habitats.';}
 else if(v==='migration'){b=text(20,28,'MIGRATION LINKS SEASONAL HABITATS',14)+box(40,65,170,'UK oak woodland','Breeding / summer food')+box(230,235,185,'West Africa','Wintering forests')+arrow('M145 142Q360 130 330 225')+dot(145+185*t,142+83*t,8)+text(20,315,'Pied flycatcher · shown southward journey',12)+text(20,336,'Returns north in spring · not a scaled route',11);c='Pied flycatchers migrate between breeding woodlands and West African wintering areas. The loop repeats one southward teaching journey; it is not a literal circular flight route or measured speed. Spring return,food supply,timing and risks matter too. Migration differs from hibernation and storing food.';}
 else{b=text(20,28,'THREE STRATEGIES · DIFFERENT RESPONSES',13)+box(35,65,370,'Migration · pied flycatcher','Moves between seasonal regions')+box(35,155,370,'Hibernation · dormouse','Metabolism greatly reduced')+box(35,245,370,'Food storage · squirrel','Caches food; can stay active');c='Species use different responses to seasonal food shortage and cold. Hibernation is more than normal sleep; food caching does not show that an active squirrel is truly hibernating. Not every woodland species uses every strategy,and individual organisms do not choose new inherited adaptations on demand.';}
}
return svg(b,c);}
